def _solid_rectangles(grid, min_height=5, min_width=5):
    h, w = len(grid), len(grid[0])
    rectangles = []
    for top in range(h):
        for bottom in range(top + min_height - 1, h):
            for left in range(w):
                color = grid[top][left]
